html:
{%- set co = frappe.db.get_single_value("Weighbridge Settings", "report_company_name") or "Rajdatta Agro Industry" -%}
{%- set addr = frappe.db.get_single_value("Weighbridge Settings", "report_address") or "" -%}
{%- set ph = frappe.db.get_single_value("Weighbridge Settings", "report_phone") or "" -%}
{%- set fd = "dd/MM/yyyy" -%}
<script>document.title = "{{ doc.name }}";</script>
<style>
@font-face { font-family: "SlipDeva"; font-weight: normal; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Regular.ttf") format("truetype"); }
@font-face { font-family: "SlipDeva"; font-weight: bold; src: url("/assets/vyavantra_weighbridge/fonts/NotoSansDevanagari-Bold.ttf") format("truetype"); }
.wbp, .wbp td, .wbp th, .wbp div, .wbp p, .wbp h2, .wbp h3 { font-family: "SlipDeva", "Noto Sans Devanagari", sans-serif; color: #111; }
.wbp { font-size: 12.5px; line-height: 1.45; }
.wbp table { width: 100%; border-collapse: collapse; }
.wbp td, .wbp th { padding: 4px 6px; border: 1px solid #555; vertical-align: top; }
.wbp th { background: #e8edf5; text-align: center; }
.wbp .head { text-align: center; border-bottom: 2px solid #0b2a5b; padding-bottom: 6px; margin-bottom: 8px; }
.wbp .head h2 { margin: 2px 0; font-size: 20px; color: #0b2a5b; }
.wbp .head .ad { font-size: 11px; color: #333; }
.wbp .title { text-align: center; font-size: 15px; font-weight: bold; margin: 6px 0 8px; text-decoration: underline; }
.wbp .r { text-align: right; } .wbp .c { text-align: center; } .wbp .b { font-weight: bold; }
.wbp .lab { background: #f3f5f9; font-weight: bold; white-space: nowrap; }
.wbp .sp { height: 8px; }
.wbp .sign td { border: none; padding-top: 46px; text-align: center; }
.wbp .tot td { font-weight: bold; background: #f3f5f9; }
.wbp .words { margin-top: 6px; }
</style>
<div class="wbp">
 <div class="head">
  <img src="/assets/vyavantra_weighbridge/images/rajdatt_logo.png" style="height:46px"><br>
  <h2>{{ co }}</h2>
  <div class="ad">{{ addr }}{% if ph %} &nbsp;|&nbsp; फोन: {{ ph }}{% endif %}</div>
 </div>
{% set st = {"Unpaid": "न भरलेले", "Partly Paid": "अंशतः भरलेले", "Paid": "भरलेले"} %}
 <div class="title">तोडणी ठेकेदार बिल</div>
 <table>
  <tr><td class="lab">बिल क्र.</td><td>{{ doc.name }}</td><td class="lab">बिल दिनांक</td><td>{{ frappe.utils.formatdate(doc.bill_date, fd) }}</td></tr>
  <tr><td class="lab">कालावधी</td><td colspan="3">{{ frappe.utils.formatdate(doc.from_date, fd) }} ते {{ frappe.utils.formatdate(doc.to_date, fd) }}</td></tr>
  <tr><td class="lab">ठेकेदार</td><td>{{ doc.contractor ~ ' - ' ~ (doc.contractor_name or '') }}</td><td class="lab">ठेकेदार प्रकार</td><td>{{ doc.contractor_type or '' }}</td></tr>
 </table>
 <div class="sp"></div>
 <table>
  <thead><tr><th>अ.क्र.</th><th>पावती क्र.</th><th>दिनांक</th><th>वाहन क्र.</th><th>गाव</th><th>निव्वळ वजन (मे. टन)</th><th>दर (₹)</th><th>रक्कम (₹)</th><th>फरक दर</th><th>फरक रक्कम</th></tr></thead>
  <tbody>
  {% for s in doc.slips %}
  <tr><td class="c">{{ loop.index }}</td><td>{{ s.slip }}</td><td class="c">{{ frappe.utils.formatdate(s.slip_date, fd) if s.slip_date else "" }}</td><td>{{ s.vehicle or "" }}</td><td>{{ s.village or "" }}</td>
   <td class="r">{{ "%.3f"|format(s.quantity or 0) }}</td><td class="r">{{ "%.2f"|format(s.rate or 0) }}</td><td class="r">{{ "%.2f"|format(s.amount or 0) }}</td><td class="r">{{ "%.2f"|format(s.farakt_rate or 0) }}</td><td class="r">{{ "%.2f"|format(s.farakt_amount or 0) }}</td></tr>
  {% endfor %}
  <tr class="tot"><td colspan="5" class="r">एकूण</td><td class="r">{{ "%.3f"|format(doc.total_quantity or 0) }}</td><td></td><td class="r">{{ "%.2f"|format(doc.total_amount or 0) }}</td><td></td><td class="r">{{ "%.2f"|format(doc.farakt_amount or 0) }}</td></tr>
  </tbody>
 </table>
 <div class="sp"></div>
 <table style="width:55%;margin-left:auto">
  <tr><td class="lab">एकूण रक्कम</td><td class="r">{{ "%.2f"|format(doc.total_amount or 0) }}</td></tr>
  {% if doc.farakt_amount %}<tr><td class="lab">फरक</td><td class="r">{{ "%.2f"|format(doc.farakt_amount) }}</td></tr>{% endif %}{% if doc.advance_deduction %}<tr><td class="lab">आगाऊ कपात</td><td class="r">{{ "%.2f"|format(doc.advance_deduction) }}</td></tr>{% endif %}{% if doc.deposit_deduction %}<tr><td class="lab">डिपॉझिट कपात</td><td class="r">{{ "%.2f"|format(doc.deposit_deduction) }}</td></tr>{% endif %}{% if doc.other_deduction %}<tr><td class="lab">इतर कपात</td><td class="r">{{ "%.2f"|format(doc.other_deduction) }}</td></tr>{% endif %}
  <tr><td class="lab">एकूण कपात</td><td class="r">{{ "%.2f"|format(doc.total_deductions or 0) }}</td></tr>
  <tr class="tot"><td style="font-size:14px">देय रक्कम (₹)</td><td class="r" style="font-size:14px">{{ "%.2f"|format(doc.net_payable or 0) }}</td></tr>
  <tr><td class="lab">भरलेली रक्कम</td><td class="r">{{ "%.2f"|format(doc.paid_amount or 0) }}</td></tr>
  <tr><td class="lab">बाकी रक्कम</td><td class="r">{{ "%.2f"|format(doc.outstanding_amount or 0) }}</td></tr>
  <tr><td class="lab">स्थिती</td><td class="r">{{ st.get(doc.payment_status, doc.payment_status or "") }}</td></tr>
 </table>
 <div class="words"><b>देय रक्कम अक्षरी:</b> {{ marathi_number_words(doc.net_payable, "रुपये") }} फक्त</div>
 {% if doc.deduction_remarks %}<p><b>कपात शेरा:</b> {{ doc.deduction_remarks }}</p>{% endif %}
 <table class="sign"><tr><td>तयार करणारा</td><td>तपासणी करणारा</td><td>स्वीकारणारा</td></tr></table>
</div>
